function tone(type,f,t,dur,vol,dest,att){const c=AU.ctx,o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.value=f;g.gain.setValueAtTime(.0001,t);g.gain.linearRampToValueAtTime(vol,t+(att||.01));g.gain.exponentialRampToValueAtTime(.0001,t+dur);o.connect(g);g.connect(dest);o.start(t);o.stop(t+dur+.05)}
function buildMel(){const R=[[0,6,10],[0,3,6,10,12],[0,4,8,12],[2,6,10,14],[0,6,8,12]];let m=5;const bar=(ch,i,first)=>{const rh=R[Math.floor(Math.random()*R.length)];const cand=ch.t.filter(x=>x>=3&&x<=9);m=cand[Math.floor(Math.random()*cand.length)];const out=[];rh.forEach((st,k)=>{if(k>0){const d=[-2,-1,-1,0,1,1,2][Math.floor(Math.random()*7)];m=Math.max(3,Math.min(9,m+d))}out.push([st,m,k===rh.length-1?4:3])});const last=out[out.length-1];const near=ch.t.filter(x=>x>=3&&x<=9).sort((a,b)=>Math.abs(a-last[1])-Math.abs(b-last[1]))[0];last[1]=near;return out};
 const part=(from,n)=>{const base=[];for(let i=0;i<n/2;i++)base.push(bar(SONG[from+i],i));for(let i=0;i<n/2;i++){const src=base[i];MEL[from+n/2+i]=(i===n/2-1)?bar(SONG[from+n/2+i],i):src.map(x=>x.slice());MEL[from+i]=base[i]}};
 MEL=new Array(16);part(0,8);part(8,8);for(let i=0;i<2;i++)MEL[i]=[]}
function noiseHit(t,type,freq,q,vol,dur){const c=AU.ctx,s2=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();f.type=type;f.frequency.value=freq;f.Q.value=q;g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(.0001,t+dur);s2.buffer=AU.nb;s2.connect(f);f.connect(g);g.connect(AU.mus);s2.start(t);s2.stop(t+dur+.02)}
function kick(t,v){const c=AU.ctx,o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.setValueAtTime(135,t);o.frequency.exponentialRampToValueAtTime(46,t+.1);g.gain.setValueAtTime(.0001,t);g.gain.linearRampToValueAtTime(v,t+.004);g.gain.exponentialRampToValueAtTime(.0001,t+.28);o.connect(g);g.connect(AU.mus);o.start(t);o.stop(t+.3)}
