function nearG(b){const c=b.route[b.i];if(c==null)return null;let best=null;[S.hq].concat(Object.keys(S.gars||{}).map(Number)).forEach(g=>{if(g==null)return;const d=dKm(c,g);if(!best||d<best[1])best=[g,d]});return best}
