const MREV=[];
async function mverify(code,p,chk){code=(code||'').trim();try{const ecd={name:'ECDSA',namedCurve:'P-256'},vp={name:'ECDSA',hash:'SHA-256'},msg=new TextEncoder().encode('BMS1|'+p),mk=await crypto.subtle.importKey('jwk',MPUB,ecd,false,['verify']);
 if(!code.startsWith('2.'))return await crypto.subtle.verify(vp,mk,unb64(code),msg);
 const[,pl,cs,sg]=code.split('.'),pb=unb64(pl),c=JSON.parse(new TextDecoder().decode(pb));
 if(!await crypto.subtle.verify(vp,mk,unb64(cs),pb))return false;if(MREV.includes(c.n)||(chk&&c.e<Date.now()))return false;
 const ak=await crypto.subtle.importKey('jwk',{kty:'EC',crv:'P-256',x:c.k.x,y:c.k.y},ecd,false,['verify']);return await crypto.subtle.verify(vp,ak,unb64(sg),msg)}catch(e){return false}}
async function memInit(){MEM=false;try{if(!USER)return;let c=localStorage.getItem(mkC());
 if(!c){const lc=localStorage.getItem('bms_code'),lp=localStorage.getItem('bms_pid');
  if(lc&&lp&&S.mclaim&&await mverify(lc,lp)){localStorage.setItem(mkP(),lp);localStorage.setItem(mkC(),lc);localStorage.removeItem('bms_code');localStorage.removeItem('bms_pid');c=lc}}
 if(c&&await mverify(c,pid())){MEM=true}}catch(e){}hdr();memBtn();if(typeof gRender==='function'&&typeof GT!=='undefined')try{gRender()}catch(e){}}
async function activateMember(){const e=$('#mcode'),c=e?e.value.trim():'';if(!c)return toast('Tempel kode aktivasi dulu');if(!(await mverify(c,pid(),1)))return toast('Kode tidak valid untuk ID Pemain ini');try{localStorage.setItem(mkC(),c)}catch(x){}MEM=true;sfx('chime');toast('💎 Membership aktif! Klaim hadiahmu di tab Member');hdr();memBtn();gRender()}
function claimMember(){if(!MEM||S.mclaim)return;S.mclaim=1;S.money+=2e12;try{newBus('Vovol B11R (Tronton)','Skylander R25 DD',1)}catch(x){}sfx('chime');toast('💎 Hadiah membership: Rp2.000.000.000.000 dan 1 bus Vovol B11R Skylander R25 DD');hdr();render();gRender()}
function memBtn(){const m=$('#mbtn');if(!m)return;if(MEM){m.textContent='💎 Member';m.removeAttribute('href');m.onclick=e=>{e.preventDefault();toast('💎 Membership aktif. Klaim hadiah di Garasi › Member')}}else{m.textContent='💎 Membership';m.href='https://wa.me/'+WANUM+'?text='+encodeURIComponent('Halo, saya ingin gabung membership Bus Manager Simulator. Nama: '+(USER||'-')+'. ID Pemain: '+pid());m.onclick=null}}
function memberHTML(){const p=pid(),msg=encodeURIComponent('Halo, saya ingin gabung membership Bus Manager Simulator. Perusahaan: '+(S.co||'-')+'. ID Pemain: '+p);
 return`<div class="gc"><b>💎 Membership</b> ${MEM?'<span class="ok">AKTIF</span>':''}<br><small class="mut">Untuk pemain yang malas mengumpulkan uang. Keuntungan: uang Rp2 Triliun, 1 bus Vovol B11R Skylander R25 DD, gratis pindah kantor pusat, gratis bangun garasi cabang, dan gratis izin trayek.</small></div>`+(MEM?`<div class="gc">${S.mclaim?'Hadiah sudah diklaim di permainan ini.':'<button class="btn" onclick="claimMember()">Klaim hadiah (Rp2 T + bus)</button>'}</div>`:`<div class="gc">ID Pemain kamu: <b>${p}</b><br><small class="mut">1) Ketuk tombol WhatsApp dan selesaikan pembayaran. 2) Admin membalas dengan kode aktivasi. 3) Tempel kode di bawah.</small><div class="row"><a class="btn" target="_blank" rel="noopener" href="https://wa.me/${WANUM}?text=${msg}" style="text-decoration:none;text-align:center">Gabung via WhatsApp</a></div><textarea id="mcode" placeholder="Tempel kode aktivasi" style="${inpS};height:70px"></textarea><div class="row"><button class="btn" onclick="activateMember()">Aktifkan</button></div></div>`)}
function laporanHTML(){const s=season();let h=`<div class="gc"><b>Kondisi pasar</b><br><small class="mut">${s.lb||'Hari biasa'} · permintaan dasar ×${s.m.toFixed(2)} · solar ${rp(fuelP())}/liter · tagihan bulanan terbayar total ${rp(S.fixPaid||0)}${S.money<0?'<br><span class="bad">Saldo minus '+(S.neg||0)+' hari</span>':''}</small></div>`;
 if(!S.buses.length)return h+'<p class="mut">Belum ada bus.</p>';
 return h+S.buses.slice().sort((a,b)=>((b.rev||0)-(b.cst||0))-((a.rev||0)-(a.cst||0))).map(b=>{const r=b.rev||0,c=b.cst||0,p=r-c;return`<div class="gc"><b>${b.name}</b><br><small class="mut">Pendapatan ${rp(r)} · biaya ${rp(c)} (solar, kru, tol, terminal, denda)</small><br><b class="${p>=0?'ok':'bad'}">Laba ${rp(p)}</b>${r?' <small class="mut">('+Math.round(p/r*100)+'% margin)</small>':''}</div>`}).join('')}
/* --- Garasi: parkir bus setelah rute selesai, jalankan lagi kapan saja --- */
let gTimer=null;
function gOpen(){$('#gar').classList.add('on');{const e=$('#gbox');if(e)e._h=null}gRender();clearInterval(gTimer);gTimer=setInterval(gRender,1000)}
function gClose(){$('#gar').classList.remove('on');clearInterval(gTimer);gTimer=null}
function gParkNow(id){const b=bus(id);if(!b||b.state!=='parkir')return;b.garage=1;b.ready=false;b.next=0;b.parkAfter=0;toast('🅿️ '+b.name+' diparkir di garasi');render();gRender()}
function gParkAfter(id){const b=bus(id);if(!b||b.state==='parkir')return;b.parkAfter=b.parkAfter?0:1;toast(b.parkAfter?b.name+' akan parkir setelah rute selesai':'Rencana parkir '+b.name+' dibatalkan');gRender()}
function gRun(id){const b=bus(id);if(!b||b.state!=='parkir')return;if(b.route.length<2)return toast('Rute belum lengkap, atur dulu di tab Rute');if(b.svcEnd)return toast(b.name+' sedang diservis');if(svcOver(b))return toast(b.name+' wajib servis dulu');departNow(id);toast('▶️ '+b.name+(b.state==='jalan'?' berangkat dari garasi':' menunggu supir atau kondektur'));render();gRender()}
let GT='garasi';
function gTab(t){GT=t;cfL=null;const el=$('#gbox');if(el)el._h=null;gRender()}
function gRender(){const el=$('#gbox');if(!el)return;const g=S.buses.filter(b=>b.garage&&b.state==='parkir'),o=S.buses.filter(b=>!(b.garage&&b.state==='parkir'));
 const nm=b=>`<b style="color:${b.color==='#ffffff'?'inherit':b.color};filter:brightness(.8)">●</b> <b>${b.name}</b>`;
 const rt=b=>b.route.length?b.route.map(c=>CITIES[c].n).join(' → '):'Belum ada rute';
 const due=S.buses.some(b=>svcOver(b)&&!b.svcEnd),TB=[['garasi','🅿️ Garasi'],['bengkel','🔧 Bengkel'+(due?' ●':'')],['kredit','💳 Kredit'+(S.loans.length?' ('+S.loans.length+')':'')],['laporan','📊 Laporan'],['kru','👥 Kru'],['usaha','🏢 Usaha'],['member','💎 Member']];
 let h=`<div class="gh"><h2 style="margin:0">${{garasi:'🅿️ Garasi',bengkel:'🔧 Bengkel',kredit:'💳 Kredit',laporan:'📊 Laporan',kru:'👥 Kru',usaha:'🏢 Usaha',member:'💎 Member'}[GT]}</h2><button class="btn alt" onclick="gClose()">Tutup</button></div><div class="ltabs" style="margin:10px 0 0">${TB.map(t=>`<button class="btn${GT===t[0]?'':' alt'}" onclick="gTab('${t[0]}')">${t[1]}</button>`).join('')}</div>`;
 if(GT==='bengkel')h+=bengkelHTML()+partsHTML();
 else if(GT==='kredit')h+=kreditHTML();
  else if(GT==='laporan')h+=laporanHTML();else if(GT==='kru')h+=kruHTML();else if(GT==='usaha')h+=usahaHTML();else if(GT==='member')h+=memberHTML();
 else{h+=`<p class="mut" style="margin:6px 0">Bus yang diparkir tidak berangkat otomatis dan tidak butuh supir atau kondektur. Jalankan kapan saja.</p><h3 style="margin:10px 0 0">Di garasi (${g.length})</h3>`;
 h+=g.length?g.map(b=>{if(b.tour)return`<div class="gc">${nm(b)}<br><small class="mut">${tourTxt(b)}${b.svcEnd?' · sedang servis':svcOver(b)?' · wajib servis':''}</small></div>`;const sv=b.svcEnd||svcOver(b),can=b.route.length>1&&!sv;return`<div class="gc">${nm(b)}<br><small class="mut">${rt(b)}${b.route.length?' · posisi '+CITIES[b.route[b.i]].n:''}${b.svcEnd?' · sedang servis':svcOver(b)?' · wajib servis':''}</small><div class="row"><button class="btn" onclick="gRun(${b.id})" ${can?'':'disabled'}>▶️ Jalankan</button></div></div>`}).join(''):'<p class="mut">Belum ada bus di garasi.</p>';
 h+=`<h3 style="margin:14px 0 0">Beroperasi (${o.length})</h3>`;
 h+=o.length?o.map(b=>{if(b.tour&&b.state==='jalan')return`<div class="gc">${nm(b)}<br><small class="mut">${tourTxt(b)} · Jalan menuju ${CITIES[b.route[b.i+b.dir]].n} (${Math.round(b.prog*100)}%)</small></div>`;let st,bt;if(b.state==='parkir'){st=b.route.length>1?(b.ready?'Menunggu berangkat '+fa(b.next):'Rute belum diaktifkan'):'Rute belum lengkap';bt=`<button class="btn alt" onclick="gParkNow(${b.id})" ${b.svcEnd?'disabled':''}>🅿️ Parkir sekarang</button>`}else if(b.state==='event'){st='Ada masalah di jalan';bt=''}else{st='Jalan menuju '+CITIES[b.route[b.i+b.dir]].n+' ('+Math.round(b.prog*100)+'%)';bt=`<button class="btn ${b.parkAfter?'':'alt'}" onclick="gParkAfter(${b.id})">${b.parkAfter?'✓ Parkir di ujung rute (batalkan)':'🅿️ Parkir setelah rute selesai'}</button>`}
  return`<div class="gc">${nm(b)}<br><small class="mut">${rt(b)} · ${st}</small>${bt?`<div class="row">${bt}</div>`:''}</div>`}).join(''):'<p class="mut">Semua bus ada di garasi.</p>';
 }
 if(el._h===h)return;el._h=h;const st=el.scrollTop,ls=[...el.querySelectorAll('.cl')].map(x=>x.scrollTop);el.innerHTML=h;el.scrollTop=st;el.querySelectorAll('.cl').forEach((x,k)=>x.scrollTop=ls[k]||0)}

