function fsSync(){const f=$('#fssp'),p=$('#fspz');if(f)f.textContent=S.spd+'x';if(p)p.textContent=S.paused?'▶':'⏸'}
let zBefore=1;
function fsEnter(){zBefore=Z;Z=1;document.body.classList.add('fs');applyZ();$('#mapwrap').scrollTop=0;fsSync();try{const e=document.documentElement;if(!document.fullscreenElement&&e.requestFullscreen)e.requestFullscreen().catch(()=>{})}catch(_){}}
function fsExit(){if(!document.body.classList.contains('fs'))return;document.body.classList.remove('fs');Z=zBefore;applyZ();try{if(document.fullscreenElement&&document.exitFullscreen)document.exitFullscreen().catch(()=>{})}catch(_){}}
function fsToggle(){document.body.classList.contains('fs')?fsExit():fsEnter()}
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement)fsExit()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('fs'))fsExit()});

